/* Read numbered PDF error tables as data. Document prose never executes as instructions. */
(function(){
'use strict';
const key=s=>s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/g,'');
function inferType(explanation){if(/Fragezeichen/i.test(explanation))return 'Interpunktion / Fragezeichen';if(/Komma/i.test(explanation))return 'Interpunktion / Komma';if(/Bezugsfehler|Wechsel von Pronomen/i.test(explanation))return 'Grammatik / Bezug';if(/Akkusativ|Dativ|Genitiv|Nominativ/i.test(explanation))return 'Grammatik / Kasus';if(/Artikel/i.test(explanation))return 'Grammatik / Artikel';if(/Rechtschreibung|Schreibweise|Grossschreibung|Kleinschreibung/i.test(explanation))return 'Rechtschreibung';return '';}
function pageLines(items){const sorted=items.filter(i=>i.str?.trim()).map(i=>({s:i.str,x:i.transform[4],y:i.transform[5],w:i.width})).sort((a,b)=>b.y-a.y||a.x-b.x),lines=[];for(const item of sorted){let row=lines.find(l=>Math.abs(l.y-item.y)<2);if(!row){row={y:item.y,items:[]};lines.push(row);}row.items.push(item);}return lines.map(l=>({...l,items:l.items.sort((a,b)=>a.x-b.x),text:l.items.map(i=>i.s).join(' ')}));}
function headers(line){const columns=[];for(const item of line.items){const k=key(item.s);let field=null;if(['nr','nummer'].includes(k))field='number';else if(['textstelle','fehlerhaftetextstelle','fehlerstelle','original'].includes(k))field='quote';else if(['korrektur','korrekturvorschlag'].includes(k))field='correction';else if(['erklarung','begrundung'].includes(k))field='explanation';else if(['p','punkte','gewicht','gewichtung'].includes(k))field='weight';else if(['fehlerart','kategorie'].includes(k))field='type';if(field)columns.push({field,x:item.x});}return ['quote','explanation','weight'].every(f=>columns.some(c=>c.field===f))?columns.sort((a,b)=>a.x-b.x):null;}
async function readPdf(file){const pdfjs=await globalThis.loadKWPDF();let loading,doc;try{loading=pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false,disableFontFace:true,useSystemFonts:false,useWorkerFetch:false,disableAutoFetch:true});doc=await loading.promise;if(doc.numPages>100)throw Error('PDF-Fehlerlisten dürfen höchstens 100 Seiten enthalten.');const errors=[],notes=[],allLines=[];let columns=null,row=null,stopped=false,seen=new Set(),hasText=false;const finish=()=>{if(!row)return;const raw=Object.fromEntries(Object.entries(row).map(([k,v])=>[k,v.join(' ').replace(/\s+/g,' ').trim()]));row=null;if(!raw.quote)return;const num=raw.number?.replace(/[.)]$/,'');if(num&&seen.has(num))throw Error('Doppelte Fehlernummer '+num+' im PDF. Bitte die Liste prüfen.');if(num)seen.add(num);const e=KW.entry({Textstelle:raw.quote,Korrektur:raw.correction||'',Erklärung:raw.explanation||'',Gewicht:raw.weight||'',Fehlerart:raw.type||inferType(raw.explanation||'')});e.typeInferred=!raw.type&&!!e.type;e.sourceQuote=raw.quote;e.sourceNumber=num||String(errors.length+1);e.fromPdf=true;errors.push(e);};
for(let pageNumber=1;pageNumber<=doc.numPages;pageNumber++){const page=await doc.getPage(pageNumber),content=await page.getTextContent(),lines=pageLines(content.items);hasText ||= lines.length>0;allLines.push(...lines.map(l=>l.text));for(const line of lines){if(/Zusätzliche Ausdruckshinweise|Nicht (?:mit)?gezählte|Stilhinweise/i.test(line.text)){finish();stopped=true;notes.push('Ungezählte Ausdrucks- oder Stilhinweise stehen im PDF; sie werden nicht als Fehler übernommen.');continue;}if(stopped)continue;const next=headers(line);if(next){columns=next;continue;}if(!columns||line.y<42)continue;const cells={};for(const item of line.items){let c=columns[0];for(const candidate of columns){if(item.x>=candidate.x-3)c=candidate;}if(item.x<columns[0].x-3)continue;(cells[c.field]??=[]).push(item.s);}const number=(cells.number||[]).join('').trim(),weight=(cells.weight||[]).join('').trim();const start=columns.some(c=>c.field==='number')?/^\d+[.)]?$/.test(number):/^\d+(?:[.,]\d+)?$/.test(weight);if(start){finish();row={};}if(row)for(const[k,v]of Object.entries(cells))(row[k]??=[]).push(...v);}page.cleanup();await new Promise(r=>setTimeout(r,0));}finish();if(!hasText)throw Error('Diese PDF enthält keinen auslesbaren Text. Bitte eine PDF mit Textebene oder eine Word-/CSV-Fehlerliste verwenden.');if(!errors.length)throw Error('Keine unterstützte Fehlertabelle gefunden. Erwartet werden Textstelle, Erklärung und Punkte, optional Nr., Fehlerart und Korrektur.');if(errors.some(e=>!Number.isFinite(e.weight)))throw Error('Mindestens eine Punktzahl wurde im PDF nicht sicher erkannt. Bitte die Fehlerliste als CSV oder Word-Tabelle laden.');const totals=[...allLines.join('\n').matchAll(/Gesamt\s*:\s*(\d+(?:[.,]\d+)?)\s*Fehlerpunkte/gi)].map(m=>Number(m[1].replace(',','.')));const total=errors.reduce((n,e)=>n+e.weight,0);if(totals.length&&totals.some(n=>Math.abs(n-total)>0.0001))throw Error('Die importierte Summe ('+total+') stimmt nicht mit «Gesamt» im PDF ('+totals.join(', ')+') überein. Der Import wurde angehalten.');if(errors.some(e=>e.typeInferred))notes.push('Die Fehlerarten wurden aus den Erklärungen abgeleitet und können vor dem Export geändert werden.');return{errors,notes,total,expectedTotal:totals[0]??null};}catch(e){if(e.name==='PasswordException')throw Error('Die PDF ist passwortgeschützt. Bitte eine ungeschützte Kopie verwenden.');throw e;}finally{if(doc)await doc.destroy();else if(loading)await loading.destroy();}}
globalThis.KWReadPdf=readPdf;
})();
